import { PageActions, PageHeader, PageLayout, useGetPageUrl } from '@ansible/ansible-ui-framework';
import { LoadingPage } from '@ansible/ansible-ui-framework/components/LoadingPage';
import { PageRoutedTabs } from '@ansible/common-ui/PageRoutedTabs';
import { useGet } from '@ansible/common-ui/crud/useGet';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';
import { HubError } from '../../../common/HubError';
import { pulpAPI } from '../../../common/api/formatPath';
import { isInsightsMode } from '../../../common/isInsights';
import { PulpItemsResponse } from '../../../common/useHubView';
import { HubRoute } from '../../../main/HubRoutes';
import { HubRemote } from './../Remotes';
import { useRemoteActions } from './../hooks/useRemoteActions';

function useErrorHandlerAndLoading<T>(
  data: T | undefined,
  error: Error | undefined,
  refresh?: () => void
) {
  if (error) {
    return <HubError error={error} handleRefresh={refresh} />;
  }

  if (!data) {
    return <LoadingPage breadcrumbs tabs />;
  }

  return null;
}

export function RemotePage() {
  const { t } = useTranslation();
  const getPageUrl = useGetPageUrl();
  const pageActions = useRemoteActions({
    onRemotesDeleted: () => {},
  });
  const params = useParams<{ id: string }>();
  const {
    data: remotesData,
    error: errorRemotes,
    refresh: refreshRemotes,
  } = useGet<PulpItemsResponse<HubRemote>>(pulpAPI`/remotes/ansible/collection/?name=${params.id}`);
  const remote = remotesData?.results?.[0];

  const loadingOrErrorRemotes = useErrorHandlerAndLoading(remote, errorRemotes, refreshRemotes);

  if (loadingOrErrorRemotes) return loadingOrErrorRemotes;

  return (
    <>
      <PageLayout>
        <PageHeader
          title={remote?.name}
          breadcrumbs={[
            { label: t('Remotes'), to: getPageUrl(HubRoute.Remotes) },
            { label: remote?.name },
          ]}
          headerActions={
            <PageActions<HubRemote>
              actions={pageActions}
              position={'right'}
              selectedItem={remote}
            />
          }
        />
        <PageRoutedTabs
          backTab={{
            label: t('Back to Remotes'),
            page: HubRoute.Remotes,
            persistentFilterKey: '',
          }}
          tabs={[
            {
              label: t('Details'),
              page: HubRoute.RemoteDetails,
            },
            // In Insights mode, show a single "Access" tab using direct Pulp API
            // In standalone mode, show separate Team/User Access tabs using Gateway API
            ...(isInsightsMode()
              ? [
                  {
                    label: t('Access'),
                    page: HubRoute.RemoteAccess,
                  },
                ]
              : [
                  {
                    label: t('Team Access'),
                    page: HubRoute.RemoteTeamAccess,
                  },
                  {
                    label: t('User Access'),
                    page: HubRoute.RemoteUserAccess,
                  },
                ]),
          ]}
          params={{ id: params.id }}
          componentParams={{ id: params.id, remote: remote }}
        />
      </PageLayout>
    </>
  );
}
